    body=json.loads(subprocess.check_output(['gh','issue','view',str(n),'-R','swccg-guild/work','--json','body']))['body']
    assert '## 14 November2026 — accepted shared-search direction and bounded pilot' not in body
    (p/(str(n)+'-body.md')).write_text(body+common+'\n'+extra+'\n',encoding='utf8')
